using VisionCore;
namespace VisionFramework;
// Managed transport, not native memory ABI. Fields: VM.PlatformSDKCS.Fixture and IVmFixturePointInfo.
public sealed class RoiRegionValue {readonly RoiDocument[] regions;public IReadOnlyList<RoiDocument> Regions=>Array.AsReadOnly(regions.Select(r=>r with{Vertices=r.Vertices?.ToArray()}).ToArray());public RoiRegionValue(IEnumerable<RoiDocument> source){regions=source.Select(r=>r with{Vertices=r.Vertices?.ToArray()}).ToArray();if(regions.Length>16)throw new ArgumentException("继承区域最多16个。");foreach(var r in regions)RoiValidator.Validate(r);}}
public sealed record FixturePose(double X=0,double Y=0,double Angle=0,double ScaleX=1,double ScaleY=1){public void Validate(){if(new[]{X,Y,Angle,ScaleX,ScaleY}.Any(x=>!double.IsFinite(x))||ScaleX<=0||ScaleY<=0)throw new ArgumentException("位置修正坐标和角度必须有限，缩放必须大于0。");}}
public sealed record FixtureValue(FixturePose Reference,FixturePose Run){public void Validate(){ArgumentNullException.ThrowIfNull(Reference);ArgumentNullException.ThrowIfNull(Run);Reference.Validate();Run.Validate();}
 // Independent affine interpretation of the recovered reference/run pose contract. Native rounding is unverified.
 public Point2 Transform(Point2 p,bool inverse=false){Validate();var a=inverse?Run:Reference;var b=inverse?Reference:Run;double angle=-a.Angle*Math.PI/180,dx=p.X-a.X,dy=p.Y-a.Y,x=(dx*Math.Cos(angle)-dy*Math.Sin(angle))/a.ScaleX,y=(dx*Math.Sin(angle)+dy*Math.Cos(angle))/a.ScaleY;angle=b.Angle*Math.PI/180;return new(b.X+x*b.ScaleX*Math.Cos(angle)-y*b.ScaleY*Math.Sin(angle),b.Y+x*b.ScaleX*Math.Sin(angle)+y*b.ScaleY*Math.Cos(angle));}
 public byte[] WarpMask(byte[] source,int width,int height,CancellationToken token=default){Validate();if(source.Length!=checked(width*height))throw new ArgumentException("位置修正掩膜尺寸无效。");var origin=Transform(new(0,0),true);var axisX=Transform(new(1,0),true);var axisY=Transform(new(0,1),true);double ax=axisX.X-origin.X,ay=axisX.Y-origin.Y,bx=axisY.X-origin.X,by=axisY.Y-origin.Y;var target=new byte[source.Length];for(int y=0;y<height;y++){token.ThrowIfCancellationRequested();for(int x=0;x<width;x++){int sx=(int)Math.Floor(origin.X+x*ax+y*bx+.5),sy=(int)Math.Floor(origin.Y+x*ay+y*by+.5);if(sx>=0&&sx<width&&sy>=0&&sy<height)target[y*width+x]=source[sy*width+sx];}}return target;}
}
